using Microsoft.Data.SqlClient;using System.Data;
namespace BilliardsManager.DAL;
public sealed class BilliardsRepository
{
 const string Cs=@"Server=localhost\SQLEXPRESS;Database=BilliardsDB;Trusted_Connection=True;TrustServerCertificate=True;";static SqlConnection Open(){var c=new SqlConnection(Cs);c.Open();return c;}
 static DataTable Fill(string sql){using var c=Open();using var a=new SqlDataAdapter(sql,c);var t=new DataTable();a.Fill(t);return t;}
 public DataTable Tables()=>Fill("SELECT MaBan,TenBan,LoaiBan,GiaTheoGio,TrangThai FROM dbo.BanBida ORDER BY MaBan");public DataTable Menu()=>Fill("SELECT MaDV,TenDV,DonGia,TonKho,LaDichVuThue FROM dbo.MenuDichVu ORDER BY TenDV");public DataTable ActiveTables()=>Fill("SELECT MaBan,TenBan FROM dbo.BanBida WHERE TrangThai=N'Đang chơi' ORDER BY TenBan");
 public int OpenTable(int table){using var c=Open();using var tx=c.BeginTransaction();try{using(var x=new SqlCommand("UPDATE dbo.BanBida SET TrangThai=N'Đang chơi' WHERE MaBan=@id AND TrangThai=N'Trống'",c,tx)){x.Parameters.Add("@id",SqlDbType.Int).Value=table;if(x.ExecuteNonQuery()!=1)throw new InvalidOperationException("Bàn không còn trống.");}int bill;using(var x=new SqlCommand("INSERT dbo.HoaDon(MaBan,GioBatDau,TrangThai) VALUES(@id,GETDATE(),0);SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){x.Parameters.Add("@id",SqlDbType.Int).Value=table;bill=Convert.ToInt32(x.ExecuteScalar());}tx.Commit();return bill;}catch{tx.Rollback();throw;}}
 public int ActiveBill(int table){using var c=Open();using var x=new SqlCommand("SELECT TOP 1 MaHD FROM dbo.HoaDon WHERE MaBan=@id AND TrangThai=0 ORDER BY MaHD DESC",c);x.Parameters.Add("@id",SqlDbType.Int).Value=table;return Convert.ToInt32(x.ExecuteScalar()??0);}
 public DataTable BillLines(int bill){using var c=Open();using var a=new SqlDataAdapter("SELECT c.MaHD,c.MaDV,m.TenDV,c.SoLuong,c.DonGia FROM dbo.ChiTietHoaDon c JOIN dbo.MenuDichVu m ON m.MaDV=c.MaDV WHERE c.MaHD=@id ORDER BY m.TenDV",c);a.SelectCommand!.Parameters.Add("@id",SqlDbType.Int).Value=bill;var t=new DataTable();a.Fill(t);return t;}
 public void SaveBillLines(DataTable rows,int bill){using var c=Open();using var tx=c.BeginTransaction();try{var a=new SqlDataAdapter();a.UpdateCommand=new SqlCommand("UPDATE dbo.ChiTietHoaDon SET SoLuong=@q,DonGia=@p WHERE MaHD=@h AND MaDV=@d",c,tx);Bind(a.UpdateCommand,"@q",SqlDbType.Int,"SoLuong");Bind(a.UpdateCommand,"@p",SqlDbType.Decimal,"DonGia");a.UpdateCommand.Parameters["@p"].Precision=18;a.UpdateCommand.Parameters["@p"].Scale=2;Bind(a.UpdateCommand,"@h",SqlDbType.Int,"MaHD");Bind(a.UpdateCommand,"@d",SqlDbType.Int,"MaDV");a.InsertCommand=new SqlCommand("INSERT dbo.ChiTietHoaDon(MaHD,MaDV,SoLuong,DonGia) VALUES(@h,@d,@q,@p)",c,tx);Bind(a.InsertCommand,"@h",SqlDbType.Int,"MaHD");Bind(a.InsertCommand,"@d",SqlDbType.Int,"MaDV");Bind(a.InsertCommand,"@q",SqlDbType.Int,"SoLuong");Bind(a.InsertCommand,"@p",SqlDbType.Decimal,"DonGia");a.InsertCommand.Parameters["@p"].Precision=18;a.InsertCommand.Parameters["@p"].Scale=2;a.DeleteCommand=new SqlCommand("DELETE dbo.ChiTietHoaDon WHERE MaHD=@h AND MaDV=@d",c,tx);Bind(a.DeleteCommand,"@h",SqlDbType.Int,"MaHD",DataRowVersion.Original);Bind(a.DeleteCommand,"@d",SqlDbType.Int,"MaDV",DataRowVersion.Original);a.Update(rows);tx.Commit();}catch{tx.Rollback();throw;}}
    static void Bind(SqlCommand x,string name,SqlDbType type,string column,DataRowVersion version=DataRowVersion.Current){var p=x.Parameters.Add(name,type);p.SourceColumn=column;p.SourceVersion=version;}
 public DataTable Pay(int bill){using var c=Open();using var tx=c.BeginTransaction();try{DateTime start;decimal rate;int table;using(var x=new SqlCommand("SELECT h.GioBatDau,b.GiaTheoGio,h.MaBan FROM dbo.HoaDon h JOIN dbo.BanBida b ON b.MaBan=h.MaBan WHERE h.MaHD=@id AND h.TrangThai=0",c,tx)){x.Parameters.Add("@id",SqlDbType.Int).Value=bill;using var r=x.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Không tìm thấy hóa đơn đang mở.");start=r.GetDateTime(0);rate=r.GetDecimal(1);table=r.GetInt32(2);}double minutes=Math.Max(1,(DateTime.Now-start).TotalMinutes);decimal game=rate*(decimal)(minutes/60d);decimal services;using(var sum=new SqlCommand("SELECT COALESCE(SUM(SoLuong*DonGia),0) FROM dbo.ChiTietHoaDon WHERE MaHD=@id",c,tx)){sum.Parameters.Add("@id",SqlDbType.Int).Value=bill;services=Convert.ToDecimal(sum.ExecuteScalar());}using(var check=new SqlCommand("SELECT m.TenDV,c.SoLuong FROM dbo.ChiTietHoaDon c JOIN dbo.MenuDichVu m ON m.MaDV=c.MaDV WHERE c.MaHD=@id AND m.LaDichVuThue=0 AND m.TonKho<c.SoLuong",c,tx)){check.Parameters.Add("@id",SqlDbType.Int).Value=bill;using var r=check.ExecuteReader();if(r.Read())throw new InvalidOperationException($"Tồn kho {r.GetString(0)} không đủ; giao dịch chưa được thanh toán.");}using(var stock=new SqlCommand("UPDATE m SET m.TonKho=m.TonKho-c.SoLuong FROM dbo.MenuDichVu m JOIN dbo.ChiTietHoaDon c ON c.MaDV=m.MaDV WHERE c.MaHD=@id AND m.LaDichVuThue=0",c,tx)){stock.Parameters.Add("@id",SqlDbType.Int).Value=bill;stock.ExecuteNonQuery();}using(var update=new SqlCommand("UPDATE dbo.HoaDon SET GioKetThuc=GETDATE(),TienGioChoi=@g,TienDichVu=@s,TrangThai=1 WHERE MaHD=@id;UPDATE dbo.BanBida SET TrangThai=N'Trống' WHERE MaBan=@table",c,tx)){var p=update.Parameters.Add("@g",SqlDbType.Decimal);p.Precision=18;p.Scale=2;p.Value=decimal.Round(game,2);var s=update.Parameters.Add("@s",SqlDbType.Decimal);s.Precision=18;s.Scale=2;s.Value=services;update.Parameters.Add("@id",SqlDbType.Int).Value=bill;update.Parameters.Add("@table",SqlDbType.Int).Value=table;update.ExecuteNonQuery();}tx.Commit();return Fill("SELECT MaHD,MaBan,GioBatDau,GioKetThuc,TienGioChoi,TienDichVu,TienGioChoi+TienDichVu AS TongTien FROM dbo.HoaDon WHERE MaHD="+bill.ToString(System.Globalization.CultureInfo.InvariantCulture));}catch{tx.Rollback();throw;}}
 public void SaveMenu(int? id,string name,decimal price,int stock,bool rental){using var c=Open();using var x=new SqlCommand(id==null?"INSERT dbo.MenuDichVu(TenDV,DonGia,TonKho,LaDichVuThue) VALUES(@n,@p,@s,@r)":"UPDATE dbo.MenuDichVu SET TenDV=@n,DonGia=@p,TonKho=@s,LaDichVuThue=@r WHERE MaDV=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,100).Value=name;var p=x.Parameters.Add("@p",SqlDbType.Decimal);p.Precision=18;p.Scale=2;p.Value=price;x.Parameters.Add("@s",SqlDbType.Int).Value=stock;x.Parameters.Add("@r",SqlDbType.Bit).Value=rental;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public DataTable Bills()=>Fill("SELECT TOP 100 h.MaHD,b.TenBan,h.GioBatDau,h.GioKetThuc,h.TienGioChoi,h.TienDichVu,h.TienGioChoi+h.TienDichVu AS TongTien,h.TrangThai FROM dbo.HoaDon h JOIN dbo.BanBida b ON b.MaBan=h.MaBan ORDER BY h.MaHD DESC");
}
